import{_ as o,o as d,c as a,ae as c}from"./chunks/framework.YL6nI5ZP.js";const u=JSON.parse('{"title":"El subsistema de malla 2D y WebGPU","description":"","frontmatter":{},"headers":[],"relativePath":"es/explanation/04-malla-2d-y-webgpu.md","filePath":"es/explanation/04-malla-2d-y-webgpu.md"}'),s={name:"es/explanation/04-malla-2d-y-webgpu.md"};function n(r,e,l,i,t,p){return d(),a("div",null,[...e[0]||(e[0]=[c('<h1 id="el-subsistema-de-malla-2d-y-webgpu" tabindex="-1">El subsistema de malla 2D y WebGPU <a class="header-anchor" href="#el-subsistema-de-malla-2d-y-webgpu" aria-label="Permalink to &quot;El subsistema de malla 2D y WebGPU&quot;">​</a></h1><p>El trabajo experimental de tránsito superficial: cómo se genera la malla 2D, se acopla a la red 1D, se serializa en el INP, se renderiza y finalmente se reimplementa en la GPU como un marcher WGSL.</p><p>Conviven dos generaciones:</p><ol><li><strong>Generador de mallas legado</strong> (<code>mesh2d.js</code>) — triangulación <code>poly2tri</code> por subcuenca con una escalera de fallback de recorte de orejas (ear clipping).</li><li><strong>Pipeline Triangle de producción</strong> (<code>mesh2dPslg.js</code> + <code>mesh2dTriangle.js</code> + <code>mesh2dTerrain.js</code>) — Delaunay restringido sobre todo el dominio vía el Triangle WASM de Shewchuk vendorizado.</li><li><strong>Marcher WebGPU</strong> (<code>public/webgpu/</code>) — una reimplementación WGSL del solver explícito local-inercial del motor, ejecutado en paralelo a (y como alternativa de) el solver 2D WASM.</li></ol><h2 id="fundamentos-de-coordenadas-—-mesh2dproj-js" tabindex="-1">Fundamentos de coordenadas — <code>mesh2dProj.js</code> <a class="header-anchor" href="#fundamentos-de-coordenadas-—-mesh2dproj-js" aria-label="Permalink to &quot;Fundamentos de coordenadas — `mesh2dProj.js`&quot;">​</a></h2><p>Toda la geometría de la malla usa <strong>metros locales relativos a un centroide origen</strong> con una aproximación equirrectangular: <code>makeTransform(origin)</code> (<code>mesh2dProj.js:16</code>); <code>METERS_PER_DEGREE_LAT = 111320</code>; lng escalado por <code>cos(lat)</code>. <code>originFromModel(Net)</code> (<code>:43</code>) = centroide de los vértices de nodos + subcuencas. No es una proyección real, pero es adecuada para dominios a escala de kilómetros.</p><h2 id="el-modelo-de-datos-de-la-malla-—-net-setindexedmesh-network-js-874" tabindex="-1">El modelo de datos de la malla — <code>Net.setIndexedMesh</code> (<code>network.js:874</code>) <a class="header-anchor" href="#el-modelo-de-datos-de-la-malla-—-net-setindexedmesh-network-js-874" aria-label="Permalink to &quot;El modelo de datos de la malla — `Net.setIndexedMesh` (`network.js:874`)&quot;">​</a></h2><div class="language-js vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">mesh2DIndexed </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  origin: { lng, lat },</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  vertices: [{ x, y, z, lng, lat, tag, nodeId }],       </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// local metres + geo + rim Z</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  triangles: [{ v:[i0,i1,i2], n, tag }],                </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// n = Manning&#39;s, tag = subcatchment id</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  vertexNodeMap: [{ vertexIndex, nodeId, cd, area }],   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 1D↔2D coupling rows</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  nodeVertexIndex: { nodeId → vertexIndex },</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  options: { solver + coupling options }</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>El array legado de celdas <code>Net.mesh2D[]</code> (anillos cerrados, ids estables <code>M2D_&lt;i+1&gt;</code>) se deriva de él para las capas del mapa. <code>inpParser.js:496-519</code> rehidrata la misma forma desde el <code>.inp</code>.</p><h2 id="construccion-del-pslg-—-mesh2dpslg-js" tabindex="-1">Construcción del PSLG — <code>mesh2dPslg.js</code> <a class="header-anchor" href="#construccion-del-pslg-—-mesh2dpslg-js" aria-label="Permalink to &quot;Construcción del PSLG — `mesh2dPslg.js`&quot;">​</a></h2><p><code>Mesh2DPslg.fromNetwork(sources, opts)</code> (<code>mesh2dPslg.js:128</code>) construye el PSLG de Triangle en fases numeradas:</p><ol><li><strong>Borde</strong> (<code>:185</code>): se proyecta un polígono GeoJSON, se simplifica con Douglas-Peucker (<code>dpSimplify</code>, <code>:53</code>) y se densifica (<code>densify</code>, <code>:84</code>); segmentos de restricción con <code>marker=1</code>; región de fondo por defecto <code>attr=0</code>. Sin borde, un <strong>dominio automático</strong> = envolvente convexa (<code>convexHull</code>, <code>:116</code>) amortiguada por <code>domainBuffer</code> (50 m por defecto).</li><li><strong>Subcuencas</strong> (<code>:271</code>): cada una se convierte en una <strong>semilla de región</strong> de Triangle (mapeada vía <code>regionAttrToSub</code>) y opcionalmente en un anillo de restricción (<code>marker=2</code>) cuando <code>useSubRings</code>.</li><li><strong>Nodos</strong> (<code>:292</code>): los nodos hidráulicos se vuelven <strong>vértices Steiner</strong> etiquetados con su id de nodo (imponiendo <code>minNodeSep</code>); con <code>useRimZ</code>, la Z del vértice = <code>invertEl + maxDepth</code> (brocal).</li><li><strong>Conductos</strong> (<code>:327</code>): los trazados de conductos se vuelven segmentos de restricción con <code>marker=100+k</code> único, mapeados de vuelta vía <code>markerToConduit</code>.</li><li><strong>Capas de restricción</strong> (<code>:349</code>): puntos/líneas/polígonos importados se vuelven vértices/segmentos de restricción (<code>marker=3</code>); los polígonos marcados <strong>&quot;bloquear flujo (impermeable)&quot;</strong> se vuelven <strong>huecos</strong> (con una salvaguarda contra &quot;tragarse el dominio&quot;).</li><li><strong>Dedupe de segmentos</strong> (<code>:409</code>) por clave de punto <code>min:max</code>; <strong>eliminación de segmentos cruzados</strong> (<code>:422</code>) vía un test <code>segsCross</code> con grid de bboxes (buckets de 25 m).</li><li><strong>Radio de aplanado</strong> (<code>:473</code>): los vértices cerca de un vértice de nodo heredan su Z de brocal (aplanado de cuencas de encharcamiento).</li><li><strong>Z de terreno</strong> (<code>:502</code>): los vértices restantes reciben <code>opts.sampleZ(x,y)</code>.</li></ol><p><code>_addPt</code> (<code>:157</code>) es un insertor de fusión con snap por hash espacial; <code>interiorPoint</code> (<code>:33</code>) elige las semillas de huecos/regiones.</p><h2 id="triangulacion-y-terreno-—-mesh2dtriangle-js-mesh2dterrain-js" tabindex="-1">Triangulación y terreno — <code>mesh2dTriangle.js</code> / <code>mesh2dTerrain.js</code> <a class="header-anchor" href="#triangulacion-y-terreno-—-mesh2dtriangle-js-mesh2dterrain-js" aria-label="Permalink to &quot;Triangulación y terreno — `mesh2dTriangle.js` / `mesh2dTerrain.js`&quot;">​</a></h2><ul><li><code>Mesh2DTriangle.triangulate(pslg, quality, ctx)</code> (<code>:92</code>) empaqueta el PSLG en arrays Float64/Int32 y corre Triangle con switches: <code>pQAY</code> (PSLG, silencioso, atributos, sin-Steiner-de-borde cuando se pide), <code>q{minAngle}</code> (default <strong>33°</strong>), <code>a{maxArea}</code> (default 200 m²) o lista de áreas regionales, <code>S{maxSteiner}</code>. Los vértices de salida se re-mapean con un <code>CoordHash</code> de 1 mm (<code>:21</code>); el n de Manning sale del atributo de región → lookup de subcuenca (<code>manningForSub</code>, <code>:36</code> — prioridad: clase de cobertura de suelo → <code>nPerv</code> → <code>nImperv</code> → default).</li><li><code>runGeneration(sources, quality, ctx, log)</code> (<code>:251</code>) orquesta con presupuestos duros: <ul><li><strong><code>trianglePointBudget</code> = 8000 puntos</strong> (el heap de Triangle WASM está fijo en 16 MB) — los modelos grandes sueltan los anillos de subcuenca + restricciones de conductos y reasignan la rugosidad por centroide.</li><li><strong><code>autoAreaCap</code></strong> (<code>:331</code>): el área máxima se limita a <code>domainArea/15000</code>, minAngle se acota a 30°, <code>maxSteiner</code> 30000, Steiner de borde deshabilitado.</li><li><strong><code>maxTriangleRegions</code> = 256</strong> (<code>:361</code>): más allá, todas las semillas de región colapsan y los tags/n se asignan por centroide.</li><li><strong>Fallback</strong> al generador poly2tri (<code>:380</code>) ante un fallo de Triangle.</li></ul></li><li><code>Mesh2DTerrain.makeSampler(settings, map)</code> (<code>mesh2dTerrain.js:24</code>): <code>MAPBOX</code> → <code>map.queryTerrainElevation</code>; <code>OPENTOPOGRAPHY_*</code> → API de bbox de OpenTopography; <code>GEOTIFF</code> → <code>readRasters</code> de geotiff.js con <strong>interpolación bilineal</strong> (<code>:109</code>), manejo de nodata, reproyección proj4 y <code>refreshBounds()</code> exponiendo la huella del ráster como dominio automático.</li><li><code>resolveVertexElevations(...)</code> (<code>:123</code>): Z de brocal primero → sampler → <strong>fallback IDW (k=4)</strong> → 0.</li><li><code>thinTerrain(sampler, domain, opts, transform)</code> (<code>:152</code>): <strong>adelgazamiento adaptativo de terreno</strong> — grid de ≤300×300 candidatos puntuados &quot;más-curvo-primero&quot; por la desviación local de la normal de superficie, aceptados con espaciado mínimo y buffer de borde.</li></ul><h2 id="acoplamiento-y-serializacion-inp" tabindex="-1">Acoplamiento y serialización INP <a class="header-anchor" href="#acoplamiento-y-serializacion-inp" aria-label="Permalink to &quot;Acoplamiento y serialización INP&quot;">​</a></h2><ul><li><code>Mesh2DCoupling.buildVertexNodeMap(indexed, nodes, opts)</code> (<code>mesh2dCoupling.js:5</code>) deduplica las filas vértice↔nodo; coeficiente de acoplamiento por defecto <code>cd = 0.65</code>.</li><li><code>Mesh2DInp.buildInput(baseInp, cells, map, options)</code> (<code>mesh2dInp.js:162</code>) rechaza las unidades US (<code>:163</code>), prefiere la malla indexada (superponiendo las opciones de solver actuales del diálogo sobre las guardadas, <code>:175-184</code>), y delega en <code>Mesh2DExport.buildInline</code> (<code>mesh2dExport.js:54</code>) o <code>buildExternal</code> (<code>:68</code>, <code>[2D_MESH_FILE]</code> + <code>.2dm</code>).</li><li>Secciones emitidas: <code>;; UNITS: SI (m)</code>, <code>;; 2D_ORIGIN lng lat</code>, <code>[2D_OPTIONS]</code>, <code>[2D_VERTICES]</code> (<code>X Y Z TAG</code>), <code>[2D_TRIANGLES]</code> (<code>V1 V2 V3 MANNINGS_N TAG</code>), <code>[2D_VERTEX_NODE_MAP]</code> opcional.</li><li><code>Mesh2DExport.optionLines</code> (<code>:22</code>) emite las opciones de solver: <code>MAX_TIMESTEP</code>, <code>DRY_DEPTH</code>, <code>COUPLING_CD</code>, <code>COUPLING_SYNC</code>, <code>THETA</code>, <code>CFL_NUMBER</code>, <code>H_MOVE</code>, <code>LTS_TIERS</code>, <code>FROUDE_MAX</code>, <code>LIMITER_EPSILON</code>, <code>FLUX_DH_EPS</code>, <code>CELL_CLOSURE</code>, <code>FACE_RECONSTRUCTION</code>, <code>VFR_MIN_WET_FRAC</code>, <code>INTEGRATOR EXPLICIT</code>, <code>COUPLING_AREA</code>, <code>RAINFALL_MODE</code> opcional, <code>REPORT_2D</code>.</li><li>El diálogo de malla (<code>mesh2dDialog.js</code>) orquesta todo desde un modal de 3 pestañas (Fuentes/Calidad/Hidráulica): <code>generate()</code> (<code>:369</code>) ensambla las fuentes, el transform, el sampler de terreno, la calidad/ctx, corre <code>Mesh2DTriangle.runGeneration</code>, resuelve las elevaciones, construye <code>vertexNodeMap</code> y llama <code>Net.setIndexedMesh</code>. Los defaults (<code>defaultSettings</code>, <code>:16</code>) persisten en <code>localStorage</code> con migraciones (v4 alinea <code>LTS_TIERS 4</code>, <code>MAX_TIMESTEP 10</code>, <code>H_MOVE 0.003</code>; v5 alinea <code>THETA 0.8</code>, <code>CFL_NUMBER 0.7</code>, <code>FROUDE_MAX 1.5</code>, <code>COUPLING_SYNC 0</code>, <code>FLUX_DH_EPS 0.004</code>, <code>VFR_MIN_WET_FRAC 0.01</code> — todo según el <code>SolverOptions2D.hpp</code> del motor / Ref Manual Vol II Cap 9 §9.11).</li></ul><h2 id="renderizado-de-la-simulacion-2d" tabindex="-1">Renderizado de la simulación 2D <a class="header-anchor" href="#renderizado-de-la-simulacion-2d" aria-label="Permalink to &quot;Renderizado de la simulación 2D&quot;">​</a></h2><p>Dos capas complementarias:</p><ul><li><strong>Overlays GeoJSON — <code>mesh2dRender.js</code>:</strong> <code>Mesh2DLayers.ensure(map)</code> (<code>:95</code>) crea fuentes/capas para puntos de vértices, isolíneas de tirante (<code>isolines</code>, <code>:32</code>), <strong>bandas</strong> de contorno de tirante (<code>contourBands</code>, <code>:50</code> — la parte seca se recorta bajo el <code>View2D.DEPTH_MASK_M</code> canónico (5 mm) para que la película de lluvia uniforme quede invisible), flechas de velocidad (<code>velocityArrows</code>, <code>:89</code>, umbral <code>mag &lt; 0.002</code>, tamaño de flecha <code>√(mag/max)</code> acotado 0.4–1.8), y bandas/isolíneas de elevación. <code>onStep(step, frame)</code> (<code>:127</code>) reconstruye el campo de tirantes de vértices (desde <code>frame.vertex.depth</code> o, cuando el motor emite tirantes por celda, ponderado por área y <strong>solo con celdas húmedas</strong> para que los tirantes húmedos nunca se filtren a vértices secos) en cada cuadro de animación. Expuesto en el árbol de capas (12 toggles).</li><li><strong>Capa Gouraud WebGL2 — <code>meshGlLayer.js</code>:</strong> <code>MeshShadeLayer</code> (<code>:6</code>) es una capa custom de Mapbox (<code>renderingMode:&#39;2d&#39;</code>) con shaders GLSL ES 3.0 y una rampa de color de 5 paradas (<code>#2e7dd1 → #26a69a → #ffca28 → #f57c00 → #d32f2f</code>). <code>setField</code> (<code>:16</code>) codifica <code>t = clamp((v−min)/(max−min))</code> con alpha solo-húmedo. <code>Mesh2DGL.ensure</code> (<code>:18</code>) agrega <code>m2d-smooth-depth-fill</code> y <code>m2d-mesh-terrain</code> bajo el relleno clásico por celda (<code>swmm-2d-mesh-fill</code>, que se colorea por triángulo vía feature-state <code>resultColor</code>, <code>results.js:393/433</code>).</li></ul><h2 id="el-marcher-webgpu-—-public-webgpu" tabindex="-1">El marcher WebGPU — <code>public/webgpu/</code> <a class="header-anchor" href="#el-marcher-webgpu-—-public-webgpu" aria-label="Permalink to &quot;El marcher WebGPU — `public/webgpu/`&quot;">​</a></h2><ul><li><strong><code>webgpuMarscher.js</code></strong> — <code>buildEdges(mesh)</code> (<code>:23</code>) es un <strong>port bit-exacto del <code>InertialEdges.cpp</code> del motor</strong> (centroide/área/lecho por triángulo, claves de borde por par ordenado de vértices, normales salientes, bordes interiores de Fase 1, <code>cell_lchar = 2·area/xiMax</code>, CSR por celda). <code>WebGPUMarcher</code> (<code>:171</code>) sube buffers SoA empaquetados y compila <strong>un pipeline de cómputo con un bind group de 16 bindings</strong> (<code>_compile</code>, <code>:338</code>) más 15 pipelines de cómputo. <code>advance(t0,t1,rain)</code> (<code>:592</code>) espeja <code>ExplicitInertialSolver::advance</code> — cadencia de rebuild 4, vía <code>K=1</code> de dt global, macro-ciclo LTS <code>K&gt;1</code>, <code>dtFloor</code> protege el colapso CFL de velocidad de Perot en f32.</li><li><strong><code>shaders/marcher.wgsl</code></strong> (el único archivo de shaders) — un port 1:1 f64→f32 de <code>InertialKernels.hpp</code>. Los parámetros viajan como un <code>array&lt;f32&gt;</code> plano (los storage bindings tipados por struct fallan en algunos drivers). Kernels: <code>faceFlux</code> (actualización de cara local-inercial de de Almeida &amp; Bates + presupuesto de positividad de la celda exportadora <code>β/3·V</code>), <code>cellUpdate</code> (descarga de celda de Perot), <code>lazySources</code>, <code>seedActive</code> (activación histerética <code>h_on = hMove+0.001</code>, <code>h_off = hMove−0.001</code>; celdas de acoplamiento fijadas), <code>halo</code>, <code>couplingExchange</code> (orificio regularizado C¹ <code>Q = cd·Aeff·√(2g)·φ</code>, drenaje limitado por <code>β·V/dt</code>, rebalse limitado por un registro de extracción por nodo), <code>cflReduce</code>/<code>cflArgmin</code> (atomicMin de dt0 bitcast + celda argmin), y el set LTS v2 (<code>settleAcc</code>, <code>tierAssign</code>, <code>faceTierAssign</code>, <code>degenTier</code>/<code>degenFaceTier</code>, <code>faceFluxLts</code>, <code>cellUpdateLts</code> con refire = <code>2^(tier_exp − face_tier)</code>).</li><li><strong><code>couplingSplit.js</code></strong> — la maquinaria del split M2 (segura para workers): <code>parse2DMesh</code>/<code>parse2DOptions</code> (<code>:18</code>/<code>:43</code>), <code>nodeOrder</code> (<code>:67</code>, índice de nodo = orden de parseo entre JUNCTIONS/OUTFALLS/STORAGE/DIVIDERS ordenados por posición global del texto — una caminata fija mal-indexa algunos INPs), <code>buildVertexStencil</code> (<code>:95</code>, pesos de partición de la unidad de Jawahar-Kamath), <code>parseCoupling</code> (<code>:144</code>, clave = <code>(invert+fullDepth)·len12</code>; <code>COUPLING_AREA DEFAULT</code> → <code>A = clamp(1.25·Amax_conduit, 0.05, 2.0)</code> m²; <strong>los puntos de vértice resuelven a la celda incidente de lecho más bajo</strong>, según <code>SurfaceRouter2D.cpp:394-412</code>), <code>build1DInp</code> (<code>:283</code>, quita las secciones 2D, fuerza <code>ALLOW_PONDING YES</code>, <strong>preserva el propio <code>VARIABLE_STEP</code> adaptativo del modelo</strong> — un pin previo a 0 corrompía el solve 1D), <code>rainMpsAt</code> (<code>:331</code>, lluvia media de pluviómetros, manejo de INTENSITY/CUMULATIVE/VOLUME), y el núcleo <strong><code>runSplit</code></strong> (<code>:400</code>): llena cada ventana de acoplamiento por tiempo, congela el estado 1D de los nodos en filas <code>cplF</code> de 9 floats, protege el estado no-finito (<code>COUPLING_STATE_NONFINITE</code>), <code>marcher.advance</code>, devuelve <code>∫Q</code> vía <code>setLatInflow(exch/dtBatch)</code> (igualando la entrega en cola de media de dos ventanas del motor), emite cuadros, calcula el balance de masa real.</li><li><strong><code>gpu2dWorker.js</code></strong> — el worker de producción (mismo contrato <code>run2d</code> que <code>openSwmm2dWorker.js</code>): carga el motor WASM <strong>solo para la parte 1D</strong>, requiere <code>maxStorageBuffersPerShaderStage: 16</code> (<code>requestGpuDevice</code>, <code>:70</code>; lanza <code>WEBGPU_UNAVAILABLE</code> si no), escribe un INP solo-1D, <code>setPondArea(tri_area)</code> por nodo de acoplamiento, y luego <code>CouplingSplit.runSplit</code> con una ventana de acoplamiento de 60 s.</li><li><strong><code>harness.html</code></strong> — página de validación M0/M1/M2. Umbrales: <strong>conservación ≤ 0.5 %, tirante medio ≤ 1e-3 m, correlación de Pearson mediana ≥ 0.5</strong>; intercambio M2 dentro de 5 %, corr temporal ≥ 0.9.</li></ul><h2 id="estado-del-roadmap-webgpu-desde-webgpu-plan-md" tabindex="-1">Estado del roadmap WebGPU (desde <code>WEBGPU_PLAN.md</code>) <a class="header-anchor" href="#estado-del-roadmap-webgpu-desde-webgpu-plan-md" aria-label="Permalink to &quot;Estado del roadmap WebGPU (desde `WEBGPU_PLAN.md`)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Hito</th><th>Alcance</th><th>Estado</th></tr></thead><tbody><tr><td>M0</td><td>Harness: detección <code>navigator.gpu</code>, device, canvas</td><td>✅ (solo Chrome con ventana; headless no tiene WebGPU)</td></tr><tr><td>M1</td><td>Marcher de dt global: faceFlux+cellUpdate+rain</td><td>✅ paridad estadística</td></tr><tr><td>M2</td><td>Acoplamiento split 1D+2D</td><td>✅ PASS (marcher-cpl: exch Δ≈0, medianCorr 0.865, temporalCorr 1.0)</td></tr><tr><td>M2.x</td><td>Acoplamiento de vértices + worker de producción</td><td>✅ Bellinge corre en GPU</td></tr><tr><td>M3</td><td>Condiciones de borde + LTS v2</td><td>✅ LTS v2 listo; NORMAL_FLOW / SPECIFIED_STAGE pendientes</td></tr><tr><td>M4</td><td>renderDepths + toggle UI WebGPU/WASM</td><td>pendiente</td></tr><tr><td>M5</td><td>Benchmark y hosting</td><td>pendiente</td></tr></tbody></table><p><strong>Límites duros y veredictos honestos registrados en el plan:</strong></p><ul><li><strong>Apple Silicon / Metal (≤10 storage buffers) no puede correr el backend</strong> — 16 storage buffers exceden el límite de Metal; el worker lanza <code>WEBGPU_UNAVAILABLE</code> y la app cae al WASM.</li><li>La divergencia f32/f64 en <code>max|Δdepth|</code> se acepta; la validación es estadística.</li><li><strong>Veredicto de rendimiento honesto:</strong> el 2D en GPU es rápido (0.13 ms/subpaso) pero la onda dinámica 1D es ~90 % del tiempo de reloj en ambos backends, por lo que el split está actualmente <em>a la par</em> con el motor, no más rápido.</li></ul>',26)])])}const g=o(s,[["render",n]]);export{u as __pageData,g as default};
